#!/usr/bin/env node
// Embeds the RainForest icon-generation skill into a JS module, so the
// serverless bundle never has to read a file at runtime through a path that may
// not survive bundling.
import { mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'Skill/rainforest-icon-generator/SKILL.md';
const TARGET = 'lib/mcp/icon-skill.generated.mjs';

const header = [
  '// @generated by scripts/generate-icon-skill.mjs — do not edit by hand.',
  `// Source of truth: ${SOURCE}`,
  '// Regenerate with: npm run sync:icon-skill',
  '',
].join('\n');

const markdown = readFileSync(join(root, SOURCE), 'utf8');
const rendered = `${header}export const ICON_SKILL_MARKDOWN = ${JSON.stringify(markdown)};\n`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(join(root, TARGET), 'utf8');
  } catch {}
  if (current !== rendered) {
    console.error(`${TARGET} is out of date — run \`npm run sync:icon-skill\``);
    process.exit(1);
  }
  console.log('icon skill asset is in sync');
} else {
  mkdirSync(dirname(join(root, TARGET)), { recursive: true });
  writeFileSync(join(root, TARGET), rendered);
  console.log(`generated ${TARGET} (${markdown.length} bytes from ${SOURCE})`);
}
